import { io } from 'socket.io-client';

let socket = null;

export const initSocket = (user) => {
  // 1. Sécurité Rôle : Si pas d'utilisateur ou si c'est l'Admin, on ne connecte RIEN
  if (!user || user.role === 'Admin') {
    if (socket) {
      socket.disconnect();
      socket = null;
    }
    console.log("Compte Admin ou déconnecté : Connexion Socket.io ignorée.");
    return null;
  }

  // 2. Si le gérant est déjà connecté, on réutilise le socket existant
  if (socket && socket.connected) return socket;

  // 3. Connexion sécurisée pour les Gérants
  const socketUrl = process.env.REACT_APP_SOCKET_URL || 'https://shop.ecash-guinee.com';
  
  socket = io(socketUrl, {
    autoConnect: true,
    withCredentials: true,
    // CORRECTION IIS : On autorise le 'polling' (HTTP) en premier. 
    // Si IIS est bien configuré, il passera automatiquement (upgrade) en 'websocket'.
    // Si IIS bloque le websocket, le gérant fonctionnera quand même grâce au polling !
    transports: ['polling', 'websocket'], 
    upgrade: true,
    reconnectionAttempts: 5, // Évite de saturer ton Windows Server en cas de coupure réseau
    reconnectionDelay: 2000
  });

  socket.on('connect', () => {
    console.log('Connecté au serveur en temps réel avec succès ! ID:', socket.id);
  });

  socket.on('connect_error', (error) => {
    console.warn('Erreur de connexion Socket (Tentative de repli...) :', error.message);
  });

  return socket;
};

// Permet de récupérer l'instance n'importe où dans le code frontend
export const getSocket = () => socket;

export default socket;